import { render, screen } from "@testing-library/react";
import { describe, expect, it } from "vitest";
import LoginPage from "./LoginPage.js";

describe("LoginPage", () => {
  it("states how to simulate a sign-in, the parameter in code", () => {
    render(<LoginPage search={{}} />);
    const page = screen.getByRole("region", { name: "Login" });
    expect(page.querySelector("code")?.textContent).toBe("?auth=1");
    expect(page).not.toHaveTextContent("redirected");
  });

  it("names where the reader returns to after a redirect", () => {
    render(<LoginPage search={{ from: "/account" }} />);
    expect(screen.getByRole("region", { name: "Login" })).toHaveTextContent(
      "You will be redirected to /account after login.",
    );
  });

  it("passes native props through and merges a consumer className after its own", () => {
    render(<LoginPage className="is-quiet" data-testid="page" search={{}} />);
    expect(screen.getByTestId("page").className).toBe(
      "ds prose-page ds login-page is-quiet",
    );
  });
});
